-- Internal human-verified incident evidence. No liability, claim submission, settlement, or payment is automated.
-- Review before applying. This file does not run against an environment by itself.
begin;

create table public.incident_claim_records(
  id uuid primary key default gen_random_uuid(),company_id uuid not null,load_id uuid,asset_id uuid,document_id uuid,
  incident_type text not null check(incident_type in('cargo_damage','accident','breakdown','reefer_temperature','other')),
  claim_status text not null check(claim_status in('evidence_only','draft','recorded_reported','under_review','resolved')),
  occurred_at timestamptz not null,location text,summary text not null check(char_length(summary) between 3 and 1000),
  counterparty text,claim_reference text,estimated_loss_cents bigint check(estimated_loss_cents is null or estimated_loss_cents>=0),
  factual_note text not null check(char_length(factual_note) between 3 and 3000),record_status text not null default'active' check(record_status in('active','voided')),
  verified_by uuid not null,request_id text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
  unique(company_id,id),unique(company_id,request_id),
  constraint incident_load_company_fk foreign key(company_id,load_id)references public.loads(company_id,id),
  constraint incident_asset_company_fk foreign key(company_id,asset_id)references public.fleet_assets(company_id,id),
  constraint incident_document_company_fk foreign key(company_id,document_id)references public.documents(company_id,id)
);
create table public.incident_claim_events(
  id uuid primary key default gen_random_uuid(),company_id uuid not null,incident_id uuid not null,event_type text not null check(event_type in('created','updated','voided')),
  before_state jsonb,after_state jsonb,factual_note text not null,actor_user_id uuid not null,request_id text not null,created_at timestamptz not null default now(),
  unique(company_id,request_id),constraint incident_event_company_fk foreign key(company_id,incident_id)references public.incident_claim_records(company_id,id)
);
create index incident_claim_company_status_idx on public.incident_claim_records(company_id,claim_status,occurred_at desc)where record_status='active';
alter table public.incident_claim_records enable row level security;alter table public.incident_claim_events enable row level security;
create policy incident_claim_authorized_select on public.incident_claim_records for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting'));
create policy incident_claim_events_authorized_select on public.incident_claim_events for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting'));
revoke all privileges on table public.incident_claim_records,public.incident_claim_events from public,anon,authenticated,service_role;
grant select on table public.incident_claim_records,public.incident_claim_events to authenticated,service_role;grant insert,update on table public.incident_claim_records to service_role;grant insert on table public.incident_claim_events to service_role;

create or replace function public.list_verified_incident_claims()returns table(id uuid,load_id uuid,load_number text,asset_id uuid,unit_number text,document_id uuid,document_title text,incident_type text,claim_status text,occurred_at timestamptz,location text,summary text,counterparty text,claim_reference text,estimated_loss_cents bigint,factual_note text,record_status text,updated_at timestamptz)
language sql stable security definer set search_path=public as $$select i.id,i.load_id,l.load_number,i.asset_id,a.unit_number,i.document_id,d.title,i.incident_type,i.claim_status,i.occurred_at,i.location,i.summary,i.counterparty,i.claim_reference,i.estimated_loss_cents,i.factual_note,i.record_status,i.updated_at from public.incident_claim_records i left join public.loads l on l.company_id=i.company_id and l.id=i.load_id left join public.fleet_assets a on a.company_id=i.company_id and a.id=i.asset_id left join public.documents d on d.company_id=i.company_id and d.id=i.document_id where i.company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting')order by i.occurred_at desc$$;

create or replace function public.list_incident_claim_context()returns table(context_kind text,context_id uuid,label text)
language sql stable security definer set search_path=public as $$select'load',l.id,l.load_number from public.loads l where l.company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety') union all select'asset',a.id,a.unit_number from public.fleet_assets a where a.company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety')and a.status<>'retired' union all select'document',d.id,d.title from public.documents d join public.document_ocr_results o on o.company_id=d.company_id and o.document_id=d.id and o.document_version_id=d.current_version_id and o.status='completed' join public.document_proposed_actions pa on pa.company_id=d.company_id and pa.document_id=d.id and pa.ocr_result_id=o.id and pa.status='approved' join public.document_approvals ap on ap.company_id=d.company_id and ap.proposed_action_id=pa.id and ap.decision='approved' where d.company_id=public.document_intake_company_id()and d.status='ready'and public.current_business_role()in('super_admin','owner','safety') order by 1,3$$;

create or replace function public.save_verified_incident_claim(p_incident_id uuid,p_load_id uuid,p_asset_id uuid,p_document_id uuid,p_incident_type text,p_claim_status text,p_occurred_at timestamptz,p_location text,p_summary text,p_counterparty text,p_claim_reference text,p_estimated_loss_cents bigint,p_note text,p_request_id text)returns uuid
language plpgsql security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();u uuid:=auth.uid();r text:=public.current_business_role();x uuid;b jsonb;a jsonb;e text;begin if c is null or u is null or r not in('super_admin','owner','safety')then raise exception'Not authorized';end if;if p_request_id is null or char_length(p_request_id)not between 8 and 200 or p_incident_type not in('cargo_damage','accident','breakdown','reefer_temperature','other')or p_claim_status not in('evidence_only','draft','recorded_reported','under_review','resolved')or p_occurred_at is null or p_occurred_at>now()+interval'1 day'or char_length(trim(p_summary))not between 3 and 1000 or char_length(trim(p_note))not between 3 and 3000 or(p_estimated_loss_cents is not null and p_estimated_loss_cents<0)then raise exception'Invalid incident facts';end if;select incident_id into x from public.incident_claim_events where company_id=c and request_id=p_request_id;if x is not null then return x;end if;if p_load_id is not null and not exists(select 1 from public.loads where company_id=c and id=p_load_id)then raise exception'Same-company load required';end if;if p_asset_id is not null and not exists(select 1 from public.fleet_assets where company_id=c and id=p_asset_id)then raise exception'Same-company asset required';end if;if p_document_id is not null and not exists(select 1 from public.documents d where d.company_id=c and d.id=p_document_id and d.status='ready'and exists(select 1 from public.document_ocr_results o join public.document_proposed_actions pa on pa.company_id=o.company_id and pa.document_id=o.document_id and pa.ocr_result_id=o.id and pa.status='approved'join public.document_approvals ap on ap.company_id=pa.company_id and ap.proposed_action_id=pa.id and ap.decision='approved'where o.company_id=d.company_id and o.document_id=d.id and o.document_version_id=d.current_version_id and o.status='completed'))then raise exception'Current approved evidence required';end if;if p_incident_id is null then insert into public.incident_claim_records(company_id,load_id,asset_id,document_id,incident_type,claim_status,occurred_at,location,summary,counterparty,claim_reference,estimated_loss_cents,factual_note,verified_by,request_id)values(c,p_load_id,p_asset_id,p_document_id,p_incident_type,p_claim_status,p_occurred_at,nullif(trim(p_location),''),trim(p_summary),nullif(trim(p_counterparty),''),nullif(trim(p_claim_reference),''),p_estimated_loss_cents,trim(p_note),u,p_request_id)returning id into x;e:='created';else select to_jsonb(v)into b from public.incident_claim_records v where v.company_id=c and v.id=p_incident_id and v.record_status='active'for update;if b is null then raise exception'Active incident not found';end if;update public.incident_claim_records set load_id=p_load_id,asset_id=p_asset_id,document_id=p_document_id,incident_type=p_incident_type,claim_status=p_claim_status,occurred_at=p_occurred_at,location=nullif(trim(p_location),''),summary=trim(p_summary),counterparty=nullif(trim(p_counterparty),''),claim_reference=nullif(trim(p_claim_reference),''),estimated_loss_cents=p_estimated_loss_cents,factual_note=trim(p_note),verified_by=u,request_id=p_request_id,updated_at=now()where company_id=c and id=p_incident_id returning id into x;e:='updated';end if;select to_jsonb(v)into a from public.incident_claim_records v where v.company_id=c and v.id=x;insert into public.incident_claim_events(company_id,incident_id,event_type,before_state,after_state,factual_note,actor_user_id,request_id)values(c,x,e,b,a,trim(p_note),u,p_request_id);return x;end$$;

create or replace function public.void_verified_incident_claim(p_incident_id uuid,p_reason text,p_request_id text)returns uuid language plpgsql security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();u uuid:=auth.uid();r text:=public.current_business_role();x uuid;b jsonb;a jsonb;begin if c is null or u is null or r not in('super_admin','owner','safety')then raise exception'Not authorized';end if;if char_length(trim(p_reason))not between 3 and 3000 or p_request_id is null or char_length(p_request_id)not between 8 and 200 then raise exception'Reason required';end if;select incident_id into x from public.incident_claim_events where company_id=c and request_id=p_request_id;if x is not null then return x;end if;select to_jsonb(v)into b from public.incident_claim_records v where v.company_id=c and v.id=p_incident_id and v.record_status='active'for update;if b is null then raise exception'Active incident not found';end if;update public.incident_claim_records set record_status='voided',updated_at=now()where company_id=c and id=p_incident_id returning id into x;select to_jsonb(v)into a from public.incident_claim_records v where v.company_id=c and v.id=x;insert into public.incident_claim_events(company_id,incident_id,event_type,before_state,after_state,factual_note,actor_user_id,request_id)values(c,x,'voided',b,a,trim(p_reason),u,p_request_id);return x;end$$;

revoke all on function public.list_verified_incident_claims(),public.list_incident_claim_context(),public.save_verified_incident_claim(uuid,uuid,uuid,uuid,text,text,timestamptz,text,text,text,text,bigint,text,text),public.void_verified_incident_claim(uuid,text,text)from public,anon;grant execute on function public.list_verified_incident_claims(),public.list_incident_claim_context(),public.save_verified_incident_claim(uuid,uuid,uuid,uuid,text,text,timestamptz,text,text,text,text,bigint,text,text),public.void_verified_incident_claim(uuid,text,text)to authenticated;
commit;
